import React, { useState, useRef } from 'react';
import axios from 'axios';

const VideoProcessor = ({ colorblindType, mode }) => {
  const [file, setFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileSelect = (event) => {
    const selectedFile = event.target.files[0];
    if (!selectedFile) return;

    if (!selectedFile.type.startsWith('video/')) {
      setError('Please select a valid video file');
      return;
    }

    setFile(selectedFile);
    setResult(null);
    setError(null);
  };

  const handleDragOver = (event) => {
    event.preventDefault();
  };

  const handleDrop = (event) => {
    event.preventDefault();
    const droppedFile = event.dataTransfer.files[0];
    if (!droppedFile) return;

    if (!droppedFile.type.startsWith('video/')) {
      setError('Please drop a valid video file');
      return;
    }

    setFile(droppedFile);
    setResult(null);
    setError(null);
  };

  const processVideo = async () => {
    if (!file) {
      setError('Please select a video file');
      return;
    }

    try {
      setProcessing(true);
      setError(null);
      setResult(null);

      const formData = new FormData();
      formData.append('video', file);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const response = await axios.post(
        'http://localhost:5000/api/process-video',
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      if (response.data.success) {
        setResult({
          success: true,
          outputFile: response.data.output_file,
          framesProcessed: response.data.frames_processed,
        });
      } else {
        setError(response.data.error || 'Processing failed');
      }
    } catch (err) {
      setError('Error processing video: ' + err.message);
    } finally {
      setProcessing(false);
    }
  };

  const downloadVideo = () => {
    if (!result?.outputFile) return;

    const link = document.createElement('a');
    link.href = `http://localhost:5000/api/download/${result.outputFile}`;
    link.download = result.outputFile;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="component-container">
      <h2>Video Processor</h2>

      {error && (
        <div className="error" style={{ marginBottom: '15px', padding: '10px' }}>
          {error}
        </div>
      )}

      <div
        className="upload-area"
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onClick={() => fileInputRef.current?.click()}
        style={{
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa',
          cursor: 'pointer',
        }}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="video/*"
          onChange={handleFileSelect}
          style={{ display: 'none' }}
        />

        {!file ? (
          <>
            <p>Drag and drop your video here</p>
            <p style={{ fontSize: '14px', color: '#666' }}>
              or click to select a video file
            </p>
          </>
        ) : (
          <>
            <p>✓ Selected: {file.name}</p>
            <p style={{ fontSize: '12px', color: '#666' }}>
              Size: {(file.size / 1024 / 1024).toFixed(2)} MB
            </p>
          </>
        )}
      </div>

      {/* PROCESS BUTTON */}
      <div style={{ marginTop: '20px', textAlign: 'center' }}>
        <button
          onClick={processVideo}
          disabled={!file || processing}
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            borderRadius: '8px',
            border: 'none',
            backgroundColor: !file || processing ? '#ccc' : '#5d35c4',
            color: '#fff',
            cursor: !file || processing ? 'not-allowed' : 'pointer',
          }}
        >
          {processing ? 'Processing…' : 'Process Video'}
        </button>
      </div>

      {/* PROCESSING BAR */}
      {processing && (
        <div style={{ marginTop: '25px', textAlign: 'center' }}>
          <p style={{ marginBottom: '10px' }}>
            Video is processing… please wait
          </p>

          <div
            style={{
              width: '80%',
              height: '8px',
              margin: '0 auto',
              backgroundColor: '#e0e0e0',
              borderRadius: '5px',
              overflow: 'hidden',
            }}
          >
            <div
              style={{
                width: '40%',
                height: '100%',
                backgroundColor: '#5d35c4',
                animation: 'loading 1.2s infinite',
              }}
            />
          </div>
        </div>
      )}

      {/* RESULT + DOWNLOAD */}
      {result?.success && !processing && (
        <div style={{ marginTop: '25px', textAlign: 'center' }}>
          <p style={{ color: '#4caf50' }}>
            ✓ Video processed successfully ({result.framesProcessed} frames)
          </p>

          <button
            onClick={downloadVideo}
            style={{
              padding: '10px 20px',
              fontSize: '16px',
              borderRadius: '8px',
              border: 'none',
              backgroundColor: '#4caf50',
              color: '#fff',
              cursor: 'pointer',
            }}
          >
            Download Processed Video
          </button>
        </div>
      )}

      {/* SIMPLE LOADING ANIMATION */}
      <style>
        {`
          @keyframes loading {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(250%); }
          }
        `}
      </style>
    </div>
  );
};

export default VideoProcessor;
